;text-decoration:none;font-size:15px;font-weight:600;padding:12px 22px;border-radius:8px;">অগ্রিম পরিশোধ করুন</a>⏎</td></tr>{% endif %}⏎<tr><td style="padding:8px 32px 0;">⏎<p style="margin:0 0 8px;font-size:13px;font-weight:600;text-transform:uppercase;letter-spacing:0.04em;color:#6b7280;">অর্ডারের বিবরণ</p>⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-top:1px solid #e5e7eb;">⏎{% for item in order.line_items %}<tr>⏎<td width="56" style="padding:12px 12px 12px 0;border-bottom:1px solid #f3f4f6;vertical-align:top;">{% if item.image_url %}<img src="{{ item.image_url }}" alt="" width="48" height="48" style="display:block;width:48px;height:48px;border-radius:8px;object-fit:cover;border:1px solid #e5e7eb;">{% endif %}</td>⏎<td style="padding:12px 0;border-bottom:1px solid #f3f4f6;font-size:14px;line-height:1.4;color:#111827;vertical-align:top;">{{ item.title }}{% if item.variant_title %}<br><span style="color:#6b7280;font-size:13px;">{{ item.variant_title }}</span>{% endif %}<br><span style="color:#6b7280;font-size:13px;">পরিমাণ {{ item.quantity }}</span></td>⏎<td align="right" style="padding:12px 0;border-bottom:1px solid #f3f4f6;font-size:14px;color:#111827;vertical-align:top;white-space:nowrap;">{{ item.line_price | money }}</td>⏎</tr>{% endfor %}⏎</table>⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin-top:8px;">⏎<tr><td style="padding:6px 0;font-size:14px;color:#374151;">সাবটোটাল</td><td align="right" style="padding:6px 0;font-size:14px;color:#374151;">{{ order.subtotal_price | money }}</td></tr>⏎{% if order.discount_price > 0 %}<tr><td style="padding:6px 0;font-size:14px;color:#374151;">ছাড়</td><td align="right" style="padding:6px 0;font-size:14px;color:#374151;">-{{ order.discount_price | money }}</td></tr>{% endif %}⏎<tr><td style="padding:6px 0;font-size:14px;color:#374151;">ডেলিভারি চার্জ</td><td align="right" style="padding:6px 0;font-size:14px;color:#374151;">{{ order.delivery_price | money }}</td></tr>⏎<tr><td style="padding:10px 0 6px;font-size:16px;font-weight:700;color:#111827;border-top:1px solid #e5e7eb;">মোট</td><td align="right" style="padding:10px 0 6px;font-size:16px;font-weight:700;color:#111827;border-top:1px solid #e5e7eb;">{{ order.total_price | money }}</td></tr>⏎{% if order.paid_amount > 0 %}<tr><td style="padding:6px 0;font-size:14px;color:#374151;">পরিশোধিত</td><td align="right" style="padding:6px 0;font-size:14px;color:#374151;">{{ order.paid_amount | money }}</td></tr>{% endif %}⏎{% if order.cod_amount > 0 %}<tr><td style="padding:6px 0;font-size:14px;color:#374151;"><strong>ডেলিভারিতে পরিশোধ</strong></td><td align="right" style="padding:6px 0;font-size:14px;color:#374151;"><strong>{{ order.cod_amount | money }}</strong></td></tr>{% endif %}⏎</table>⏎</td></tr>⏎{% if order.shipping_address.address %}<tr><td style="padding:20px 32px 0;">⏎<p style="margin:0 0 6px;font-size:13px;font-weight:600;text-transform:uppercase;letter-spacing:0.04em;color:#6b7280;">ডেলিভারি ঠিকানা</p>⏎<p style="margin:0;font-size:14px;line-height:1.6;color:#374151;">{{ order.shipping_address.name }}<br>{{ order.shipping_address.address }}{% if order.shipping_address.area %}, {{ order.shipping_address.area }}{% endif %}{% if order.shipping_address.district %}, {{ order.shipping_address.district }}{% endif %}<br>{{ order.shipping_address.phone }}</p>⏎</td></tr>{% endif %}⏎<tr><td style="padding:28px 32px 28px;">⏎<p style="margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>⏎</td></tr>⏎</table>⏎</td></tr>⏎</table>⏎</body>⏎</html>', '⏎', char(10)), 'bn');
INSERT INTO "notification_defaults" ("channel", "event", "subject", "template", "language") VALUES ('EMAIL', 'PAYMENT_RECEIVED', 'অর্ডার {{ order.name }} এর পেমেন্ট পেয়েছি', replace('{% assign accent = shop.accent_color | default: "#111827" %}<!doctype html>⏎<html lang="bn">⏎<head>⏎<meta charset="utf-8">⏎<meta name="viewport" content="width=device-width, initial-scale=1">⏎<title>আপনার পেমেন্ট পেয়েছি</title>⏎</head>⏎<body style="margin:0;padding:0;background:#f4f5f7;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f4f5f7;">⏎<tr><td align="center" style="padding:32px 12px;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background:#ffffff;border-radius:12px;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;color:#111827;">⏎<tr><td style="padding:28px 32px 0;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr>⏎<td>{% if shop.logo_url %}<img src="{{ shop.logo_url }}" alt="{{ shop.name }}" height="36" style="display:block;height:36px;max-width:180px;border:0;">{% else %}<span style="font-size:20px;font-weight:700;color:#111827;">{{ shop.name }}</span>{% endif %}</td>⏎<td align="right" style="font-size:13px;color:#6b7280;">{% if order.name %}অর্ডার {{ order.name }}{% endif %}</td>⏎</tr></table>⏎</td></tr>⏎<tr><td style="padding:24px 32px 4px;">⏎<h1 style="margin:0 0 12px;font-size:22px;line-height:1.3;color:#111827;">আপনার পেমেন্ট পেয়েছি</h1>⏎<p style="margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;">প্রিয় {{ customer.first_name | default: "গ্রাহক" }}, অর্ডার {{ order.name }} এর জন্য <strong>{{ payment.amount | money }}</strong> পেয়েছি। ধন্যবাদ!</p>⏎{% if order.due_amount > 0 %}<p style="margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;">ডেলিভারিতে বাকি: <strong>{{ order.due_amount | money }}</strong>।</p>{% endif %}⏎</td></tr>⏎⏎<tr><td style="padding:8px 32px 0;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-top:1px solid #e5e7eb;">⏎<tr><td style="padding:6px 0;font-size:14px;color:#374151;">অর্ডার</td><td align="right" style="padding:6px 0;font-size:14px;color:#374151;">{{ order.name }}</td></tr>⏎<tr><td style="padding:6px 0;font-size:14px;color:#374151;">পণ্য</td><td align="right" style="padding:6px 0;font-size:14px;color:#374151;">{{ order.item_count }}</td></tr>⏎<tr><td style="padding:6px 0;font-size:14px;color:#374151;">মোট</td><td align="right" style="padding:6px 0;font-size:14px;color:#374151;">{{ order.total_price | money }}</td></tr>⏎{% if order.cod_amount > 0 %}<tr><td style="padding:6px 0;font-size:14px;color:#374151;">ডেলিভারিতে পরিশোধ</td><td align="right" style="padding:6px 0;font-size:14px;color:#374151;">{{ order.cod_amount | money }}</td></tr>{% endif %}⏎</table>⏎</td></tr>⏎<tr><td style="padding:28px 32px 28px;">⏎<p style="margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>⏎</td></tr>⏎</table>⏎</td></tr>⏎</table>⏎</body>⏎</html>', '⏎', char(10)), 'bn');
INSERT INTO "notification_defaults" ("channel", "event", "subject", "template", "language") VALUES ('WHATSAPP', 'ORDER_CONFIRMED', NULL, replace('প্রিয় {{customer_first_name}}, আপনার অর্ডার {{order_number}} কনফার্ম হয়েছে, আমরা প্রস্তুত করছি। ডেলিভারির সময় পরিশোধ করবেন {{cod_amount}}।⏎⏎ধন্যবাদ, {{store_name}} টিম', '⏎', char(10)), 'bn');
INSERT INTO "notification_defaults" ("channel", "event", "subject", "template", "language") VALUES ('WHATSAPP', 'PRE_ORDER_CONFIRMED', NULL, replace('প্রিয় {{customer_first_name}}, আপনার প্রি-অর্ডার {{order_number}} কনফার্ম হয়েছে। পণ্য স্টকে আসার সাথে সাথে আমরা পাঠিয়ে দেব।⏎⏎ধন্যবাদ, {{store_name}} টিম', '⏎', char(10)), 'bn');
INSERT INTO "notification_defaults" ("channel", "event", "subject", "template", "language") VALUES ('WHATSAPP', 'ADVANCE_REQUIRED', NULL, replace('প্রিয় {{customer_first_name}}, অর্ডার {{order_number}} কনফার্ম করতে {{advance_amount}} অগ্রিম পরিশোধ করুন এই লিংকে: {{track_order_url}} এরপরই আমরা পাঠিয়ে দেব।⏎⏎ধন্যবাদ, {{store_name}} টিম', '⏎', char(10)), 'bn');
INSERT INTO "notification_defaults" ("channel", "event", "subject", "template", "language") VALUES ('EMAIL', 'PAYMENT_FAILED', 'অর্ডার {{ order.name }} এর পেমেন্ট সম্পন্ন হয়নি', replace('{% assign accent = shop.accent_color | default: "#111827" %}<!doctype html>⏎<html lang="bn">⏎<head>⏎<meta charset="utf-8">⏎<meta name="viewport" content="width=device-width, initial-scale=1">⏎<title>আপনার পেমেন্ট সম্পন্ন হয়নি</title>⏎</head>⏎<body style="margin:0;padding:0;background:#f4f5f7;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f4f5f7;">⏎<tr><td align="center" style="padding:32px 12px;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background:#ffffff;border-radius:12px;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;color:#111827;">⏎<tr><td style="padding:28px 32px 0;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr>⏎<td>{% if shop.logo_url %}<img src="{{ shop.logo_url }}" alt="{{ shop.name }}" height="36" style="display:block;height:36px;max-width:180px;border:0;">{% else %}<span style="font-size:20px;font-weight:700;color:#111827;">{{ shop.name }}</span>{% endif %}</td>⏎<td align="right" style="font-size:13px;color:#6b7280;">{% if order.name %}অর্ডার {{ order.name }}{% endif %}</td>⏎</tr></table>⏎</td></tr>⏎<tr><td style="padding:24px 32px 4px;">⏎<h1 style="margin:0 0 12px;font-size:22px;line-height:1.3;color:#111827;">আপনার পেমেন্ট সম্পন্ন হয়নি</h1>⏎<p style="margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;">প্রিয় {{ customer.first_name | default: "গ্রাহক" }}, অর্ডার {{ order.name }} এর জন্য <strong>{{ payment.amount | money }}</strong> পেমেন্ট সম্পন্ন হয়নি। কোনো টাকা কাটা হয়নি। নিচে আবার চেষ্টা করতে পারেন।</p>⏎</td></tr>⏎{% if order.status_url %}<tr><td style="padding:12px 32px 4px;">⏎<a href="{{ order.status_url }}" style="display:inline-block;background:{{ accent }};color:#ffffff;text-decoration:none;font-size:15px;font-weight:600;padding:12px 22px;border-radius:8px;">আবার চেষ্টা করুন</a>⏎</td></tr>{% endif %}⏎<tr><td style="padding:8px 32px 0;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-top:1px solid #e5e7eb;">⏎<tr><td style="padding:6px 0;font-size:14px;color:#374151;">অর্ডার</td><td align="right" style="padding:6px 0;font-size:14px;color:#374151;">{{ order.name }}</td></tr>⏎<tr><td style="padding:6px 0;font-size:14px;color:#374151;">পণ্য</td><td align="right" style="padding:6px 0;font-size:14px;color:#374151;">{{ order.item_count }}</td></tr>⏎<tr><td style="padding:6px 0;font-size:14px;color:#374151;">মোট</td><td align="right" style="padding:6px 0;font-size:14px;color:#374151;">{{ order.total_price | money }}</td></tr>⏎{% if order.cod_amount > 0 %}<tr><td style="padding:6px 0;font-size:14px;color:#374151;">ডেলিভারিতে পরিশোধ</td><td align="right" style="padding:6px 0;font-size:14px;color:#374151;">{{ order.cod_amount | money }}</td></tr>{% endif %}⏎</table>⏎</td></tr>⏎<tr><td style="padding:28px 32px 28px;">⏎<p style="margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>⏎</td></tr>⏎</table>⏎</td></tr>⏎</table>⏎</body>⏎</html>', '⏎', char(10)), 'bn');
INSERT INTO "notification_defaults" ("channel", "event", "subject", "template", "language") VALUES ('EMAIL', 'ORDER_SHIPPED', 'অর্ডার {{ order.name }} পাঠানো হয়েছে', replace('{% assign accent = shop.accent_color | default: "#111827" %}<!doctype html>⏎<html lang="bn">⏎<head>⏎<meta charset="utf-8">⏎<meta name="viewport" content="width=device-width, initial-scale=1">⏎<title>আপনার অর্ডার পথে আছে</title>⏎</head>⏎<body style="margin:0;padding:0;background:#f4f5f7;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f4f5f7;">⏎<tr><td align="center" style="padding:32px 12px;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background:#ffffff;border-radius:12px;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;color:#111827;">⏎<tr><td style="padding:28px 32px 0;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr>⏎<td>{% if shop.logo_url %}<img src="{{ shop.logo_url }}" alt="{{ shop.name }}" height="36" style="display:block;height:36px;max-width:180px;border:0;">{% else %}<span style="font-size:20px;font-weight:700;color:#111827;">{{ shop.name }}</span>{% endif %}</td>⏎<td align="right" style="font-size:13px;color:#6b7280;">{% if order.name %}অর্ডার {{ order.name }}{% endif %}</td>⏎</tr></table>⏎</td></tr>⏎<tr><td style="padding:24px 32px 4px;">⏎<h1 style="margin:0 0 12px;font-size:22px;line-height:1.3;color:#111827;">আপনার অর্ডার পথে আছে</h1>⏎<p style="margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;">প্রিয় {{ customer.first_name | default: "গ্রাহক" }}, আপনার অর্ডার {{ order.name }} {{ shipment.courier | default: "কুরিয়ার" }} এর কাছে দেওয়া হয়েছে।</p>⏎{% if shipment.tracking_number %}<p style="margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;">ট্র্যাকিং নম্বর: <strong>{{ shipment.tracking_number }}</strong></p>{% endif %}⏎{% if order.cod_amount > 0 %}<p style="margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;">ডেলিভারির সময় <strong>{{ order.cod_amount | money }}</strong> প্রস্তুত রাখুন।</p>{% endif %}⏎</td></tr>⏎{% if shipment.tracking_url or order.status_url %}<tr><td style="padding:12px 32px 4px;">⏎<a href="{{ shipment.tracking_url | default: order.status_url }}" style="display:inline-block;background:{{ accent }};color:#ffffff;text-decoration:none;font-size:15px;font-weight:600;padding:12px 22px;border-radius:8px;">পার্সেল ট্র্যাক করুন</a>⏎</td></tr>{% endif %}⏎<tr><td style="padding:8px 32px 0;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-top:1px solid #e5e7eb;">⏎<tr><td style="padding:6px 0;font-size:14px;color:#374151;">অর্ডার</td><td align="right" style="padding:6px 0;font-size:14px;color:#374151;">{{ order.name }}</td></tr>⏎<tr><td style="padding:6px 0;font-size:14px;color:#374151;">পণ্য</td><td align="right" style="padding:6px 0;font-size:14px;color:#374151;">{{ order.item_count }}</td></tr>⏎<tr><td style="padding:6px 0;font-size:14px;color:#374151;">মোট</td><td align="right" style="padding:6px 0;font-size:14px;color:#374151;">{{ order.total_price | money }}</td></tr>⏎{% if order.cod_amount > 0 %}<tr><td style="padding:6px 0;font-size:14px;color:#374151;">ডেলিভারিতে পরিশোধ</td><td align="right" style="padding:6px 0;font-size:14px;color:#374151;">{{ order.cod_amount | money }}</td></tr>{% endif %}⏎</table>⏎</td></tr>⏎<tr><td style="padding:28px 32px 28px;">⏎<p style="margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>⏎</td></tr>⏎</table>⏎</td></tr>⏎</table>⏎</body>⏎</html>', '⏎', char(10)), 'bn');
INSERT INTO "notification_defaults" ("channel", "event", "subject", "template", "language") VALUES ('SMS', 'ORDER_CONFIRMED', NULL, 'আপনার অর্ডার {{order_number}} কনফার্ম হয়েছে। ডেলিভারিতে পরিশোধ: {{cod_amount}} - {{store_name}}', 'bn');
INSERT INTO "notification_defaults" ("channel", "event", "subject", "template", "language") VALUES ('EMAIL', 'OUT_FOR_DELIVERY', 'অর্ডার {{ order.name }} আজ ডেলিভারি হবে', replace('{% assign accent = shop.accent_color | default: "#111827" %}<!doctype html>⏎<html lang="bn">⏎<head>⏎<meta charset="utf-8">⏎<meta name="viewport" content="width=device-width, initial-scale=1">⏎<title>আপনার অর্ডার আজ পৌঁছাবে</title>⏎</head>⏎<body style="margin:0;padding:0;background:#f4f5f7;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f4f5f7;">⏎<tr><td align="center" style="padding:32px 12px;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background:#ffffff;border-radius:12px;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;color:#111827;">⏎<tr><td style="padding:28px 32px 0;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr>⏎<td>{% if shop.logo_url %}<img src="{{ shop.logo_url }}" alt="{{ shop.name }}" height="36" style="display:block;height:36px;max-width:180px;border:0;">{% else %}<span style="font-size:20px;font-weight:700;color:#111827;">{{ shop.name }}</span>{% endif %}</td>⏎<td align="right" style="font-size:13px;color:#6b7280;">{% if order.name %}অর্ডার {{ order.name }}{% endif %}</td>⏎</tr></table>⏎</td></tr>⏎<tr><td style="padding:24px 32px 4px;">⏎<h1 style="margin:0 0 12px;font-size:22px;line-height:1.3;color:#111827;">আপনার অর্ডার আজ পৌঁছাবে</h1>⏎<p style="margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;">প্রিয় {{ customer.first_name | default: "গ্রাহক" }}, আপনার অর্ডার {{ order.name }} আজ ডেলিভারির জন্য বের হয়েছে{% if shipment.courier %} ({{ shipment.courier }}){% endif %}। ফোন খোলা রাখুন।</p>⏎{% if order.cod_amount > 0 %}<p style="margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;">ডেলিভারি ম্যানের জন্য <strong>{{ order.cod_amount | money }}</strong> প্রস্তুত রাখুন।</p>{% endif %}⏎</td></tr>⏎{% if shipment.tracking_url or order.status_url %}<tr><td style="padding:12px 32px 4px;">⏎<a href="{{ shipment.tracking_url | default: order.status_url }}" style="display:inline-block;background:{{ accent }};color:#ffffff;text-decoration:none;font-size:15px;font-weight:600;padding:12px 22px;border-radius:8px;">পার্সেল ট্র্যাক করুন</a>⏎</td></tr>{% endif %}⏎⏎<tr><td style="padding:28px 32px 28px;">⏎<p style="margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>⏎</td></tr>⏎</table>⏎</td></tr>⏎</table>⏎</body>⏎</html>', '⏎', char(10)), 'bn');
INSERT INTO "notification_defaults" ("channel", "event", "subject", "template", "language") VALUES ('EMAIL', 'DELIVERY_FAILED', 'অর্ডার {{ order.name }} ডেলিভারি দেওয়া যায়নি', replace('{% assign accent = shop.accent_color | default: "#111827" %}<!doctype html>⏎<html lang="bn">⏎<head>⏎<meta charset="utf-8">⏎<meta name="viewport" content="width=device-width, initial-scale=1">⏎<title>কুরিয়ার আপনাকে পায়নি</title>⏎</head>⏎<body style="margin:0;padding:0;background:#f4f5f7;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f4f5f7;">⏎<tr><td align="center" style="padding:32px 12px;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background:#ffffff;border-radius:12px;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;color:#111827;">⏎<tr><td style="padding:28px 32px 0;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr>⏎<td>{% if shop.logo_url %}<img src="{{ shop.logo_url }}" alt="{{ shop.name }}" height="36" style="display:block;height:36px;max-width:180px;border:0;">{% else %}<span style="font-size:20px;font-weight:700;color:#111827;">{{ shop.name }}</span>{% endif %}</td>⏎<td align="right" style="font-size:13px;color:#6b7280;">{% if order.name %}অর্ডার {{ order.name }}{% endif %}</td>⏎</tr></table>⏎</td></tr>⏎<tr><td style="padding:24px 32px 4px;">⏎<h1 style="margin:0 0 12px;font-size:22px;line-height:1.3;color:#111827;">কুরিয়ার আপনাকে পায়নি</h1>⏎<p style="margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;">প্রিয় {{ customer.first_name | default: "গ্রাহক" }}, কুরিয়ার আপনার অর্ডার {{ order.name }} ডেলিভারি দিতে গিয়ে আপনাকে পায়নি।</p>⏎<p style="margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;">আবার পাঠাতে {% if shop.phone %}{{ shop.phone }} নম্বরে কল করুন বা {% endif %}এই ইমেইলের উত্তর দিন।</p>⏎</td></tr>⏎{% if shipment.tracking_url or order.status_url %}<tr><td style="padding:12px 32px 4px;">⏎<a href="{{ shipment.tracking_url | default: order.status_url }}" style="display:inline-block;background:{{ accent }};color:#ffffff;text-decoration:none;font-size:15px;font-weight:600;padding:12px 22px;border-radius:8px;">পার্সেল ট্র্যাক করুন</a>⏎</td></tr>{% endif %}⏎⏎<tr><td style="padding:28px 32px 28px;">⏎<p style="margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>⏎</td></tr>⏎</table>⏎</td></tr>⏎</table>⏎</body>⏎</html>', '⏎', char(10)), 'bn');
INSERT INTO "notification_defaults" ("channel", "event", "subject", "template", "language") VALUES ('EMAIL', 'ORDER_DELIVERED', 'অর্ডার {{ order.name }} ডেলিভারি হয়েছে', replace('{% assign accent = shop.accent_color | default: "#111827" %}<!doctype html>⏎<html lang="bn">⏎<head>⏎<meta charset="utf-8">⏎<meta name="viewport" content="width=device-width, initial-scale=1">⏎<title>আপনার অর্ডার ডেলিভারি হয়েছে</title>⏎</head>⏎<body style="margin:0;padding:0;background:#f4f5f7;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f4f5f7;">⏎<tr><td align="center" style="padding:32px 12px;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background:#ffffff;border-radius:12px;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;color:#111827;">⏎<tr><td style="padding:28px 32px 0;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr>⏎<td>{% if shop.logo_url %}<img src="{{ shop.logo_url }}" alt="{{ shop.name }}" height="36" style="display:block;height:36px;max-width:180px;border:0;">{% else %}<span style="font-size:20px;font-weight:700;color:#111827;">{{ shop.name }}</span>{% endif %}</td>⏎<td align="right" style="font-size:13px;color:#6b7280;">{% if order.name %}অর্ডার {{ order.name }}{% endif %}</td>⏎</tr></table>⏎</td></tr>⏎<tr><td style="padding:24px 32px 4px;">⏎<h1 style="margin:0 0 12px;font-size:22px;line-height:1.3;color:#111827;">আপনার অর্ডার ডেলিভারি হয়েছে</h1>⏎<p style="margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;">প্রিয় {{ customer.first_name | default: "গ্রাহক" }}, আপনার অর্ডার {{ order.name }} ডেলিভারি হয়েছে। আশা করি পছন্দ হয়েছে!</p>⏎<p style="margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;">কোনো সমস্যা হলে এই ইমেইলের উত্তর দিন{% if shop.phone %} বা {{ shop.phone }} নম্বরে কল করুন{% endif %}।</p>⏎</td></tr>⏎⏎<tr><td style="padding:8px 32px 0;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-top:1px solid #e5e7eb;">⏎<tr><td style="padding:6px 0;font-size:14px;color:#374151;">অর্ডার</td><td align="right" style="padding:6px 0;font-size:14px;color:#374151;">{{ order.name }}</td></tr>⏎<tr><td style="padding:6px 0;font-size:14px;color:#374151;">পণ্য</td><td align="right" style="padding:6px 0;font-size:14px;color:#374151;">{{ order.item_count }}</td></tr>⏎<tr><td style="padding:6px 0;font-size:14px;color:#374151;">মোট</td><td align="right" style="padding:6px 0;font-size:14px;color:#374151;">{{ order.total_price | money }}</td></tr>⏎{% if order.cod_amount > 0 %}<tr><td style="padding:6px 0;font-size:14px;color:#374151;">ডেলিভারিতে পরিশোধ</td><td align="right" style="padding:6px 0;font-size:14px;color:#374151;">{{ order.cod_amount | money }}</td></tr>{% endif %}⏎</table>⏎</td></tr>⏎<tr><td style="padding:28px 32px 28px;">⏎<p style="margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>⏎</td></tr>⏎</table>⏎</td></tr>⏎</table>⏎</body>⏎</html>', '⏎', char(10)), 'bn');
INSERT INTO "notification_defaults" ("channel", "event", "subject", "template", "language") VALUES ('WHATSAPP', 'PAYMENT_RECEIVED', NULL, replace('প্রিয় {{customer_first_name}}, অর্ডার {{order_number}} এর জন্য আপনার {{payment_amount}} পেমেন্ট আমরা পেয়েছি। ধন্যবাদ!⏎⏎{{store_name}} টিম', '⏎', char(10)), 'bn');
INSERT INTO "notification_defaults" ("channel", "event", "subject", "template", "language") VALUES ('EMAIL', 'ORDER_CANCELLED', 'অর্ডার {{ order.name }} বাতিল হয়েছে', replace('{% assign accent = shop.accent_color | default: "#111827" %}<!doctype html>⏎<html lang="bn">⏎<head>⏎<meta charset="utf-8">⏎<meta name="viewport" content="width=device-width, initial-scale=1">⏎<title>আপনার অর্ডার বাতিল হয়েছে</title>⏎</head>⏎<body style="margin:0;padding:0;background:#f4f5f7;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f4f5f7;">⏎<tr><td align="center" style="padding:32px 12px;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background:#ffffff;border-radius:12px;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;color:#111827;">⏎<tr><td style="padding:28px 32px 0;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr>⏎<td>{% if shop.logo_url %}<img src="{{ shop.logo_url }}" alt="{{ shop.name }}" height="36" style="display:block;height:36px;max-width:180px;border:0;">{% else %}<span style="font-size:20px;font-weight:700;color:#111827;">{{ shop.name }}</span>{% endif %}</td>⏎<td align="right" style="font-size:13px;color:#6b7280;">{% if order.name %}অর্ডার {{ order.name }}{% endif %}</td>⏎</tr></table>⏎</td></tr>⏎<tr><td style="padding:24px 32px 4px;">⏎<h1 style="margin:0 0 12px;font-size:22px;line-height:1.3;color:#111827;">আপনার অর্ডার বাতিল হয়েছে</h1>⏎<p style="margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;">প্রিয় {{ customer.first_name | default: "গ্রাহক" }}, আপনার অর্ডার {{ order.name }} বাতিল করা হয়েছে।</p>⏎{% if order.paid_amount > 0 %}<p style="margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;">এই অর্ডারের জন্য আপনি {{ order.paid_amount | money }} পরিশোধ করেছিলেন। রিফান্ডের বিষয়ে আমরা যোগাযোগ করব।</p>{% endif %}⏎<p style="margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;">প্রশ্ন থাকলে এই ইমেইলের উত্তর দিন{% if shop.phone %} বা {{ shop.phone }} নম্বরে কল করুন{% endif %}।</p>⏎</td></tr>⏎⏎<tr><td style="padding:8px 32px 0;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-top:1px solid #e5e7eb;">⏎<tr><td style="padding:6px 0;font-size:14px;color:#374151;">অর্ডার</td><td align="right" style="padding:6px 0;font-size:14px;color:#374151;">{{ order.name }}</td></tr>⏎<tr><td style="padding:6px 0;font-size:14px;color:#374151;">পণ্য</td><td align="right" style="padding:6px 0;font-size:14px;color:#374151;">{{ order.item_count }}</td></tr>⏎<tr><td style="padding:6px 0;font-size:14px;color:#374151;">মোট</td><td align="right" style="padding:6px 0;font-size:14px;color:#374151;">{{ order.total_price | money }}</td></tr>⏎{% if order.cod_amount > 0 %}<tr><td style="padding:6px 0;font-size:14px;color:#374151;">ডেলিভারিতে পরিশোধ</td><td align="right" style="padding:6px 0;font-size:14px;color:#374151;">{{ order.cod_amount | money }}</td></tr>{% endif %}⏎</table>⏎</td></tr>⏎<tr><td style="padding:28px 32px 28px;">⏎<p style="margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>⏎</td></tr>⏎</table>⏎</td></tr>⏎</table>⏎</body>⏎</html>', '⏎', char(10)), 'bn');
INSERT INTO "notification_defaults" ("channel", "event", "subject", "template", "language") VALUES ('EMAIL', 'RETURN_INITIATED', 'অর্ডার {{ order.name }} ফেরত আসছে', replace('{% assign accent = shop.accent_color | default: "#111827" %}<!doctype html>⏎<html lang="bn">⏎<head>⏎<meta charset="utf-8">⏎<meta name="viewport" content="width=device-width, initial-scale=1">⏎<title>আপনার অর্ডার ফেরত আসছে</title>⏎</head>⏎<body style="margin:0;padding:0;background:#f4f5f7;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f4f5f7;">⏎<tr><td align="center" style="padding:32px 12px;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background:#ffffff;border-radius:12px;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;color:#111827;">⏎<tr><td style="padding:28px 32px 0;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr>⏎<td>{% if shop.logo_url %}<img src="{{ shop.logo_url }}" alt="{{ shop.name }}" height="36" style="display:block;height:36px;max-width:180px;border:0;">{% else %}<span style="font-size:20px;font-weight:700;color:#111827;">{{ shop.name }}</span>{% endif %}</td>⏎<td align="right" style="font-size:13px;color:#6b7280;">{% if order.name %}অর্ডার {{ order.name }}{% endif %}</td>⏎</tr></table>⏎</td></tr>⏎<tr><td style="padding:24px 32px 4px;">⏎<h1 style="margin:0 0 12px;font-size:22px;line-height:1.3;color:#111827;">আপনার অর্ডার ফেরত আসছে</h1>⏎<p style="margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;">প্রিয় {{ customer.first_name | default: "গ্রাহক" }}, অর্ডার {{ order.name }} এর পার্সেল আমাদের কাছে ফেরত আসছে।</p>⏎<p style="margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;">প্রশ্ন থাকলে এই ইমেইলের উত্তর দিন{% if shop.phone %} বা {{ shop.phone }} নম্বরে কল করুন{% endif %}।</p>⏎</td></tr>⏎⏎⏎<tr><td style="padding:28px 32px 28px;">⏎<p style="margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>⏎</td></tr>⏎</table>⏎</td></tr>⏎</table>⏎</body>⏎</html>', '⏎', char(10)), 'bn');
INSERT INTO "notification_defaults" ("channel", "event", "subject", "template", "language") VALUES ('WHATSAPP', 'CART_REMINDER', NULL, replace('প্রিয় {{customer_first_name}}, আপনার কার্টে {{cart_total}} মূল্যের পণ্য রয়ে গেছে। অর্ডার শেষ করুন এখানে: {{cart_url}} টাকা দেবেন ডেলিভারির সময়।⏎⏎{{store_name}} টিম', '⏎', char(10)), 'bn');
INSERT INTO "notification_defaults" ("channel", "event", "subject", "template", "language") VALUES ('EMAIL', 'ORDER_RETURNED', 'অর্ডার {{ order.name }} এর ফেরত পেয়েছি', replace('{% assign accent = shop.accent_color | default: "#111827" %}<!doctype html>⏎<html lang="bn">⏎<head>⏎<meta charset="utf-8">⏎<meta name="viewport" content="width=device-width, initial-scale=1">⏎<title>ফেরত পার্সেল পেয়েছি</title>⏎</head>⏎<body style="margin:0;padding:0;background:#f4f5f7;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f4f5f7;">⏎<tr><td align="center" style="padding:32px 12px;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background:#ffffff;border-radius:12px;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;color:#111827;">⏎<tr><td style="padding:28px 32px 0;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr>⏎<td>{% if shop.logo_url %}<img src="{{ shop.logo_url }}" alt="{{ shop.name }}" height="36" style="display:block;height:36px;max-width:180px;border:0;">{% else %}<span style="font-size:20px;font-weight:700;color:#111827;">{{ shop.name }}</span>{% endif %}</td>⏎<td align="right" style="font-size:13px;color:#6b7280;">{% if order.name %}অর্ডার {{ order.name }}{% endif %}</td>⏎</tr></table>⏎</td></tr>⏎<tr><td style="padding:24px 32px 4px;">⏎<h1 style="margin:0 0 12px;font-size:22px;line-height:1.3;color:#111827;">ফেরত পার্সেল পেয়েছি</h1>⏎<p style="margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;">প্রিয় {{ customer.first_name | default: "গ্রাহক" }}, অর্ডার {{ order.name }} এর ফেরত পার্সেল আমাদের কাছে পৌঁছেছে।</p>⏎{% if order.paid_amount > 0 %}<p style="margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;">আপনার {{ order.paid_amount | money }} পেমেন্টের বিষয়ে আমরা যোগাযোগ করব।</p>{% endif %}⏎</td></tr>⏎⏎⏎<tr><td style="padding:28px 32px 28px;">⏎<p style="margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>⏎</td></tr>⏎</table>⏎</td></tr>⏎</table>⏎</body>⏎</html>', '⏎', char(10)), 'bn');
INSERT INTO "notification_defaults" ("channel", "event", "subject", "template", "language") VALUES ('EMAIL', 'CART_REMINDER', 'আপনার কার্টে পণ্য রয়ে গেছে', replace('{% assign accent = shop.accent_color | default: "#111827" %}<!doctype html>⏎<html lang="bn">⏎<head>⏎<meta charset="utf-8">⏎<meta name="viewport" content="width=device-width, initial-scale=1">⏎<title>আপনার কার্ট অপেক্ষা করছে</title>⏎</head>⏎<body style="margin:0;padding:0;background:#f4f5f7;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f4f5f7;">⏎<tr><td align="center" style="padding:32px 12px;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background:#ffffff;border-radius:12px;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;color:#111827;">⏎<tr><td style="padding:28px 32px 0;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr>⏎<td>{% if shop.logo_url %}<img src="{{ shop.logo_url }}" alt="{{ shop.name }}" height="36" style="display:block;height:36px;max-width:180px;border:0;">{% else %}<span style="font-size:20px;font-weight:700;color:#111827;">{{ shop.name }}</span>{% endif %}</td>⏎<td align="right" style="font-size:13px;color:#6b7280;">{% if order.name %}অর্ডার {{ order.name }}{% endif %}</td>⏎</tr></table>⏎</td></tr>⏎<tr><td style="padding:24px 32px 4px;">⏎<h1 style="margin:0 0 12px;font-size:22px;line-height:1.3;color:#111827;">আপনার কার্ট অপেক্ষা করছে</h1>⏎<p style="margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;">প্রিয় {{ customer.first_name | default: "গ্রাহক" }}, {{ shop.name }} এ আপনার কার্টে এই পণ্যগুলো রয়ে গেছে। এক মিনিটে অর্ডার শেষ করুন, টাকা দেবেন ডেলিভারির সময়।</p>⏎</td></tr>⏎{% if cart.url %}<tr><td style="padding:12px 32px 4px;">⏎<a href="{{ cart.url }}" style="display:inline-block;background:{{ accent }};color:#ffffff;text-decoration:none;font-size:15px;font-weight:600;padding:12px 22px;border-radius:8px;">অর্ডার শেষ করুন</a>⏎</td></tr>{% endif %}⏎<tr><td style="padding:8px 32px 0;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-top:1px solid #e5e7eb;">⏎{% for item in cart.line_items %}<tr>⏎<td width="56" style="padding:12px 12px 12px 0;border-bottom:1px solid #f3f4f6;vertical-align:top;">{% if item.image_url %}<img src="{{ item.image_url }}" alt="" width="48" height="48" style="display:block;width:48px;height:48px;border-radius:8px;object-fit:cover;border:1px solid #e5e7eb;">{% endif %}</td>⏎<td style="padding:12px 0;border-bottom:1px solid #f3f4f6;font-size:14px;line-height:1.4;color:#111827;vertical-align:top;">{{ item.title }}{% if item.variant_title %}<br><span style="color:#6b7280;font-size:13px;">{{ item.variant_title }}</span>{% endif %}<br><span style="color:#6b7280;font-size:13px;">পরিমাণ {{ item.quantity }}</span></td>⏎<td align="right" style="padding:12px 0;border-bottom:1px solid #f3f4f6;font-size:14px;color:#111827;vertical-align:top;white-space:nowrap;">{{ item.line_price | money }}</td>⏎</tr>{% endfor %}⏎</table>⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin-top:8px;">⏎<tr><td style="padding:10px 0 6px;font-size:16px;font-weight:700;color:#111827;">মোট</td><td align="right" style="padding:10px 0 6px;font-size:16px;font-weight:700;color:#111827;">{{ cart.total | money }}</td></tr>⏎</table>⏎</td></tr>⏎<tr><td style="padding:28px 32px 28px;">⏎<p style="margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>⏎</td></tr>⏎</table>⏎</td></tr>⏎</table>⏎</body>⏎</html>', '⏎', char(10)), 'bn');
INSERT INTO "notification_defaults" ("channel", "event", "subject", "template", "language") VALUES ('EMAIL', 'REVIEW_REQUEST', 'অর্ডার {{ order.name }} কেমন লাগলো?', replace('{% assign accent = shop.accent_color | default: "#111827" %}<!doctype html>⏎<html lang="bn">⏎<head>⏎<meta charset="utf-8">⏎<meta name="viewport" content="width=device-width, initial-scale=1">⏎<title>আপনার মতামত জানান</title>⏎</head>⏎<body style="margin:0;padding:0;background:#f4f5f7;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f4f5f7;">⏎<tr><td align="center" style="padding:32px 12px;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background:#ffffff;border-radius:12px;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;color:#111827;">⏎<tr><td style="padding:28px 32px 0;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr>⏎<td>{% if shop.logo_url %}<img src="{{ shop.logo_url }}" alt="{{ shop.name }}" height="36" style="display:block;height:36px;max-width:180px;border:0;">{% else %}<span style="font-size:20px;font-weight:700;color:#111827;">{{ shop.name }}</span>{% endif %}</td>⏎<td align="right" style="font-size:13px;color:#6b7280;">{% if order.name %}অর্ডার {{ order.name }}{% endif %}</td>⏎</tr></table>⏎</td></tr>⏎<tr><td style="padding:24px 32px 4px;">⏎<h1 style="margin:0 0 12px;font-size:22px;line-height:1.3;color:#111827;">আপনার মতামত জানান</h1>⏎<p style="margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;">প্রিয় {{ customer.first_name | default: "গ্রাহক" }}, আশা করি অর্ডার {{ order.name }} এর পণ্য পছন্দ হয়েছে। এক মিনিটের একটি রিভিউ অন্য ক্রেতাদের এবং আমাদের অনেক সাহায্য করবে।</p>⏎</td></tr>⏎{% if shop.review_url %}<tr><td style="padding:12px 32px 4px;">⏎<a href="{{ shop.review_url }}" style="display:inline-block;background:{{ accent }};color:#ffffff;text-decoration:none;font-size:15px;font-weight:600;padding:12px 22px;border-radius:8px;">রিভিউ দিন</a>⏎</td></tr>{% endif %}⏎<tr><td style="padding:8px 32px 0;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-top:1px solid #e5e7eb;">⏎<tr><td style="padding:6px 0;font-size:14px;color:#374151;">অর্ডার</td><td align="right" style="padding:6px 0;font-size:14px;color:#374151;">{{ order.name }}</td></tr>⏎<tr><td style="padding:6px 0;font-size:14px;color:#374151;">পণ্য</td><td align="right" style="padding:6px 0;font-size:14px;color:#374151;">{{ order.item_count }}</td></tr>⏎<tr><td style="padding:6px 0;font-size:14px;color:#374151;">মোট</td><td align="right" style="padding:6px 0;font-size:14px;color:#374151;">{{ order.total_price | money }}</td></tr>⏎{% if order.cod_amount > 0 %}<tr><td style="padding:6px 0;font-size:14px;color:#374151;">ডেলিভারিতে পরিশোধ</td><td align="right" style="padding:6px 0;font-size:14px;color:#374151;">{{ order.cod_amount | money }}</td></tr>{% endif %}⏎</table>⏎</td></tr>⏎<tr><td style="padding:28px 32px 28px;">⏎<p style="margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>⏎</td></tr>⏎</table>⏎</td></tr>⏎</table>⏎</body>⏎</html>', '⏎', char(10)), 'bn');
INSERT INTO "notification_defaults" ("channel", "event", "subject", "template", "language") VALUES ('WHATSAPP', 'ORDER_CREATED', NULL, replace('প্রিয় {{customer_first_name}}, আপনার অর্ডার {{order_number}} আমরা পেয়েছি, মোট মূল্য {{total}}। শিপ করার আগে আমরা আপনার সাথে কনফার্ম করে নেব।⏎⏎{{store_name}} থেকে কেনাকাটার জন্য ধন্যবাদ।', '⏎', char(10)), 'bn');
INSERT INTO "notification_defaults" ("channel", "event", "subject", "template", "language") VALUES ('WHATSAPP', 'PAYMENT_FAILED', NULL, replace('প্রিয় {{customer_first_name}}, অর্ডার {{order_number}} এর জন্য আপনার {{payment_amount}} পেমেন্ট সম্পন্ন হয়নি। এই লিংকে আবার চেষ্টা করুন: {{track_order_url}} যেকোনো সময়।⏎⏎{{store_name}} টিম', '⏎', char(10)), 'bn');
INSERT INTO "notification_defaults" ("channel", "event", "subject", "template", "language") VALUES ('WHATSAPP', 'ORDER_SHIPPED', NULL, replace('প্রিয় {{customer_first_name}}, আপনার অর্ডার {{order_number}} পাঠানো হয়েছে, কুরিয়ার: {{courier_name}}। ট্র্যাকিং নম্বর: {{tracking_number}}। ট্র্যাক করুন এখানে: {{tracking_url}} যেকোনো সময়।⏎⏎{{store_name}} টিম', '⏎', char(10)), 'bn');
INSERT INTO "notification_defaults" ("channel", "event", "subject", "template", "language") VALUES ('WHATSAPP', 'OUT_FOR_DELIVERY', NULL, replace('প্রিয় {{customer_first_name}}, আপনার অর্ডার {{order_number}} আজ ডেলিভারির জন্য বের হয়েছে। ডেলিভারি ম্যানের জন্য {{cod_amount}} প্রস্তুত রাখুন এবং ফোন খোলা রাখুন।⏎⏎{{store_name}} টিম', '⏎', char(10)), 'bn');
INSERT INTO "notification_defaults" ("channel", "event", "subject", "template", "language") VALUES ('WHATSAPP', 'DELIVERY_FAILED', NULL, replace('প্রিয় {{customer_first_name}}, কুরিয়ার আপনার অর্ডার {{order_number}} ডেলিভারি দিতে গিয়ে আপনাকে পায়নি। আবার পাঠাতে {{store_phone}} নম্বরে কল করুন বা এখানে উত্তর দিন।⏎⏎{{store_name}} টিম', '⏎', char(10)), 'bn');
INSERT INTO "notification_defaults" ("channel", "event", "subject", "template", "language") VALUES ('WHATSAPP', 'ORDER_DELIVERED', NULL, replace('প্রিয় {{customer_first_name}}, আপনার অর্ডার {{order_number}} ডেলিভারি হয়েছে। আশা করি পছন্দ হয়েছে! কোনো সমস্যা হলে এখানে জানান।⏎⏎{{store_name}} টিম', '⏎', char(10)), 'bn');
INSERT INTO "notification_defaults" ("channel", "event", "subject", "template", "language") VALUES ('WHATSAPP', 'ORDER_CANCELLED', NULL, replace('প্রিয় {{customer_first_name}}, আপনার অর্ডার {{order_number}} বাতিল করা হয়েছে। কোনো প্রশ্ন থাকলে {{store_phone}} নম্বরে কল করুন বা এখানে উত্তর দিন।⏎⏎{{store_name}} টিম', '⏎', char(10)), 'bn');
INSERT INTO "notification_defaults" ("channel", "event", "subject", "template", "language") VALUES ('WHATSAPP', 'RETURN_INITIATED', NULL, replace('প্রিয় {{customer_first_name}}, অর্ডার {{order_number}} এর পার্সেল আমাদের কাছে ফেরত আসছে। কোনো প্রশ্ন থাকলে {{store_phone}} নম্বরে কল করুন বা এখানে উত্তর দিন।⏎⏎{{store_name}} টিম', '⏎', char(10)), 'bn');
INSERT INTO "notification_defaults" ("channel", "event", "subject", "template", "language") VALUES ('WHATSAPP', 'ORDER_RETURNED', NULL, replace('প্রিয় {{customer_first_name}}, অর্ডার {{order_number}} এর ফেরত পার্সেল আমরা পেয়েছি। শীঘ্রই আপনার সাথে যোগাযোগ করব।⏎⏎{{store_name}} টিম', '⏎', char(10)), 'bn');
