ndif %}</p>⏎</td></tr>⏎</table>⏎</td></tr>⏎</table>⏎</body>⏎</html>', '⏎', char(10)), '2026-10-27T17:19:28.904Z', '2026-10-27T17:19:30.820Z', 'Order shipped', '[]', '00000000-0000-4000-8000-000000000001', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 0, 0);
